// Generates src/tones.css from the functional map + hue registry.
// Run from the repo root: bun packages/kern-tokens/scripts/gen-tones-css.mjs
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import {
  functional,
  isFunctionalHuePair,
  isFunctionalTone,
} from "../src/functional.ts";
import { varName } from "../src/resolve.ts";
import { getHue, TONE_ROLES } from "../src/tones.ts";

const OUT = join(new URL("..", import.meta.url).pathname, "src/tones.css");

const lines = [
  "/* Generated by scripts/gen-tones-css.mjs from the functional map. */",
  "/* Tone entries follow the scheme via --md-sys-color-* role variables. */",
  "/* Hue pairs read --spectrum-<hue>-<step> (emitted by scripts/gen-css.mjs). */",
  "",
];

for (const [domain, table] of Object.entries(functional)) {
  const d = domain.replace(/(?<!^)(?=[A-Z])/g, "-").toLowerCase();
  for (const [key, value] of Object.entries(table)) {
    const cls = `.tone-${d}-${key}`;
    if (isFunctionalTone(value)) {
      const roles = TONE_ROLES[value];
      lines.push(
        `${cls} {`,
        `  background-color: var(${varName(roles.bg)});`,
        `  color: var(${varName(roles.fg)});`,
        `}`,
        "",
      );
    } else if (isFunctionalHuePair(value)) {
      const ramp = getHue(value.hue);
      if (!ramp) throw new Error(`Unknown hue in functional map: ${value.hue}`);
      lines.push(
        `${cls} {`,
        `  background-color: var(--spectrum-${value.hue}-${value.bg});`,
        `  color: var(--spectrum-${value.hue}-${value.fg});`,
        `}`,
        "",
      );
    } else {
      lines.push(
        `${cls} {`,
        `  background-color: ${value.static.bg};`,
        `  color: ${value.static.fg};`,
        `}`,
        "",
      );
    }
  }
}

writeFileSync(OUT, `${lines.join("\n").trimEnd()}\n`);
console.log(`wrote ${OUT}`);
